draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // dog ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 90);
  ctx.lineTo(W/2 - 40, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 - 90);
  ctx.lineTo(W/2 + 40, H/2 - 60);
  ctx.stroke();

  // dog eyes
  ctx.beginPath();
  ctx.arc(W/2 - 10, H/2 - 80, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H/2 - 80, 5, 0, 2 * Math.PI);
  ctx.fill();

  // dog appeasement smile
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 60, 20, 0, Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 60, 20, Math.PI, 2 * Math.PI);
  ctx.setLineDash([5, 5]);
  ctx.stroke();
  ctx.setLineDash([]);

  // tongue
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 40 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
